def re_arrange(arr, n):
    pos = []
    neg = []
    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])
    result = []
    for i in range(min(len(pos), len(neg))):
        result.append(neg[i])
        result.append(pos[i])
    if len(pos) > len(neg):
        result.extend(pos[len(neg):])
    elif len(neg) > len(pos):
        result.extend(neg[len(pos):])
    return result

